        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "ru", "Veil работает только из меню-бара: нет значка в Dock, нет в ⌘-Tab, нет меню вверху экрана. Окно открывается через «Открыть окно» в меню-баре, а приложение продолжает работать после закрытия окна."),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "zh", "仅从菜单栏运行 Veil：没有程序坞图标，不出现在 ⌘-Tab 中，屏幕顶部也没有菜单。仍可通过菜单栏项中的「打开窗口」打开窗口，关闭窗口后应用继续运行。"),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "es", "Ejecuta Veil solo desde la barra de menús: sin icono en el Dock, sin entrada en ⌘-Tab, sin menús en la parte superior. La ventana sigue accesible con «Abrir ventana» en el icono de la barra de menús y la app sigue funcionando al cerrarla."),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "hi", "Veil केवल मेन्यू बार से चलता है: कोई डॉक आइकन नहीं, ⌘-Tab में नहीं, स्क्रीन के ऊपर मेन्यू नहीं। विंडो मेन्यू बार आइटम के «विंडो खोलें» से खुलती है, और विंडो बंद करने पर ऐप चलता रहता है।"),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "ar", "تشغيل Veil من شريط القوائم فقط: بلا أيقونة في Dock، وبلا ظهور في ⌘-Tab، وبلا قوائم أعلى الشاشة. تبقى النافذة متاحة عبر «فتح النافذة» في عنصر شريط القوائم، ويستمر التطبيق بالعمل بعد إغلاقها."),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "fr", "Veil ne tourne que depuis la barre de menus : pas d'icône dans le Dock, pas d'entrée ⌘-Tab, pas de menus en haut de l'écran. La fenêtre reste accessible via « Ouvrir la fenêtre » dans l'icône de la barre de menus, et l'app continue de tourner une fois fermée."),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "pt", "Executa o Veil só pela barra de menus: sem ícone no Dock, sem entrada no ⌘-Tab, sem menus no topo da tela. A janela continua acessível por «Abrir janela» no item da barra de menus, e o app segue rodando depois de fechada."),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "de", "Veil läuft nur über die Menüleiste: kein Dock-Symbol, kein ⌘-Tab-Eintrag, keine Menüs am oberen Bildschirmrand. Das Fenster bleibt über „Fenster öffnen“ im Menüleistensymbol erreichbar, und die App läuft nach dem Schließen weiter."),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "ja", "Veil をメニューバーだけで動かします。Dock アイコンも ⌘-Tab の項目も画面上部のメニューもなくなります。ウインドウはメニューバー項目の「ウインドウを開く」から開け、閉じてもアプリは動き続けます。"),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "id", "Menjalankan Veil hanya dari bilah menu: tanpa ikon Dock, tanpa entri ⌘-Tab, tanpa menu di atas layar. Jendela tetap bisa dibuka lewat «Buka Jendela» pada item bilah menu, dan aplikasi terus berjalan setelah ditutup."),
        ("Runs Veil from the menu bar alone: no Dock tile, no ⌘-Tab entry, no menus at the top of the screen. The window stays reachable through Open Window in the menu bar item, and the app keeps running when you close it.", "tr", "Veil yalnızca menü çubuğundan çalışır: Dock simgesi yok, ⌘-Tab girdisi yok, ekranın üstünde menü yok. Pencereye menü çubuğu ögesindeki «Pencereyi Aç» ile ulaşılır ve pencere kapatılınca uygulama çalışmayı sürdürür."),
