        ("Add one to send an application, a domain or a network through a particular server.", "ru", "Добавьте правило, чтобы направить приложение, домен или сеть через конкретный сервер."),
        ("Add one to send an application, a domain or a network through a particular server.", "zh", "添加规则，把某个应用、域名或网段发往指定服务器。"),
        ("Add one to send an application, a domain or a network through a particular server.", "es", "Añade una para enviar una aplicación, un dominio o una red por un servidor concreto."),
        ("Add one to send an application, a domain or a network through a particular server.", "hi", "किसी ऐप, डोमेन या नेटवर्क को किसी खास सर्वर से भेजने के लिए नियम जोड़ें।"),
        ("Add one to send an application, a domain or a network through a particular server.", "ar", "أضف قاعدة لتوجيه تطبيق أو نطاق أو شبكة عبر خادم محدد."),
        ("Add one to send an application, a domain or a network through a particular server.", "fr", "Ajoutez-en une pour envoyer une application, un domaine ou un réseau via un serveur précis."),
        ("Add one to send an application, a domain or a network through a particular server.", "pt", "Adicione uma para enviar um aplicativo, domínio ou rede por um servidor específico."),
        ("Add one to send an application, a domain or a network through a particular server.", "de", "Füge eine hinzu, um ein Programm, eine Domain oder ein Netz über einen bestimmten Server zu leiten."),
        ("Add one to send an application, a domain or a network through a particular server.", "ja", "特定のサーバーへアプリ・ドメイン・ネットワークを送るルールを追加します。"),
        ("Add one to send an application, a domain or a network through a particular server.", "id", "Tambahkan satu untuk mengirim aplikasi, domain, atau jaringan lewat server tertentu."),
        ("Add one to send an application, a domain or a network through a particular server.", "tr", "Bir uygulamayı, alan adını ya da ağı belirli bir sunucudan geçirmek için kural ekleyin."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "ru", "Правила по приложениям работают в режиме TUN с нативным ядром, включённым в настройках."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "zh", "应用规则需要在设置中启用原生内核的 TUN 模式。"),
        ("Application rules need TUN mode with the native core enabled in Settings.", "es", "Las reglas por aplicación requieren el modo TUN con el núcleo nativo activado en Ajustes."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "hi", "ऐप नियमों के लिए Settings में native core वाला TUN मोड चाहिए।"),
        ("Application rules need TUN mode with the native core enabled in Settings.", "ar", "قواعد التطبيقات تتطلب وضع TUN مع تفعيل النواة الأصلية في الإعدادات."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "fr", "Les règles par application nécessitent le mode TUN avec le cœur natif activé dans les réglages."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "pt", "Regras por aplicativo exigem o modo TUN com o núcleo nativo ativado nas Configurações."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "de", "Programmregeln brauchen den TUN-Modus mit dem nativen Kern, aktiviert in den Einstellungen."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "ja", "アプリ単位のルールには、設定でネイティブコアを有効にした TUN モードが必要です。"),
        ("Application rules need TUN mode with the native core enabled in Settings.", "id", "Aturan aplikasi memerlukan mode TUN dengan core native yang diaktifkan di Pengaturan."),
        ("Application rules need TUN mode with the native core enabled in Settings.", "tr", "Uygulama kuralları, Ayarlar'da yerel çekirdek açıkken TUN modunu gerektirir."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "ru", "Совпадение по приложению обеспечивает ядро sing-box в режиме TUN. Ядро Xray пропускает такие правила, а не расширяет их."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "zh", "应用匹配由 TUN 模式下的 sing-box 内核完成。Xray 路径会跳过这类规则，而不是放宽它们。"),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "es", "La coincidencia por aplicación la aplica el núcleo sing-box en modo TUN. La vía Xray omite estas reglas en lugar de ampliarlas."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "hi", "ऐप मिलान TUN मोड में sing-box core करता है। Xray पथ ऐसे नियमों को चौड़ा करने के बजाय छोड़ देता है।"),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "ar", "مطابقة التطبيقات تنفّذها نواة sing-box في وضع TUN. مسار Xray يتخطى هذه القواعد بدل توسيعها."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "fr", "La correspondance par application est assurée par le cœur sing-box en mode TUN. La voie Xray ignore ces règles au lieu de les élargir."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "pt", "A correspondência por aplicativo é feita pelo núcleo sing-box no modo TUN. O caminho Xray ignora essas regras em vez de ampliá-las."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "de", "Programm-Treffer setzt der sing-box-Kern im TUN-Modus durch. Der Xray-Weg überspringt solche Regeln, statt sie auszuweiten."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "ja", "アプリの一致は TUN モードの sing-box コアが処理します。Xray 経路はこうしたルールを広げず、そのまま飛ばします。"),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "id", "Pencocokan aplikasi dijalankan core sing-box dalam mode TUN. Jalur Xray melewati aturan ini alih-alih memperlebarnya."),
        ("Application matching is enforced by the sing-box core in TUN mode. The Xray path skips these rules rather than widening them.", "tr", "Uygulama eşleşmesini TUN modunda sing-box çekirdeği uygular. Xray yolu bu kuralları genişletmek yerine atlar."),
        ("Rules — top to bottom, first match wins", "ru", "Правила — сверху вниз, срабатывает первое совпадение"),
        ("Rules — top to bottom, first match wins", "zh", "规则 — 自上而下，先匹配先生效"),
        ("Rules — top to bottom, first match wins", "es", "Reglas: de arriba abajo, gana la primera coincidencia"),
        ("Rules — top to bottom, first match wins", "hi", "नियम — ऊपर से नीचे, पहला मिलान लागू"),
        ("Rules — top to bottom, first match wins", "ar", "القواعد — من الأعلى للأسفل، أول تطابق يفوز"),
        ("Rules — top to bottom, first match wins", "fr", "Règles — de haut en bas, la première correspondance gagne"),
        ("Rules — top to bottom, first match wins", "pt", "Regras — de cima para baixo, vence a primeira correspondência"),
        ("Rules — top to bottom, first match wins", "de", "Regeln — von oben nach unten, der erste Treffer gewinnt"),
        ("Rules — top to bottom, first match wins", "ja", "ルール — 上から下へ、最初に一致したものが有効"),
        ("Rules — top to bottom, first match wins", "id", "Aturan — dari atas ke bawah, kecocokan pertama menang"),
        ("Rules — top to bottom, first match wins", "tr", "Kurallar — yukarıdan aşağıya, ilk eşleşme geçerli"),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "ru", "Правило срабатывает, когда совпали все заполненные поля. Домены: example.com, domain:example.com, keyword:google, geosite:netflix. IP: 1.2.3.0/24, geoip:cn."),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "zh", "所有已填字段都匹配时规则才生效。域名：example.com、domain:example.com、keyword:google、geosite:netflix。IP：1.2.3.0/24、geoip:cn。"),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "es", "Una regla coincide cuando coinciden todos los campos rellenados. Dominios: example.com, domain:example.com, keyword:google, geosite:netflix. IP: 1.2.3.0/24, geoip:cn."),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "hi", "नियम तभी लागू होता है जब सभी भरे हुए फ़ील्ड मेल खाएँ। डोमेन: example.com, domain:example.com, keyword:google, geosite:netflix। IP: 1.2.3.0/24, geoip:cn।"),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "ar", "تتطابق القاعدة عندما تتطابق كل الحقول المعبأة. النطاقات: example.com وdomain:example.com وkeyword:google وgeosite:netflix. عناوين IP: 1.2.3.0/24 وgeoip:cn."),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "fr", "Une règle correspond quand tous les champs remplis correspondent. Domaines : example.com, domain:example.com, keyword:google, geosite:netflix. IP : 1.2.3.0/24, geoip:cn."),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "pt", "Uma regra corresponde quando todos os campos preenchidos correspondem. Domínios: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn."),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "de", "Eine Regel trifft zu, wenn alle ausgefüllten Felder zutreffen. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn."),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "ja", "入力したすべての条件が一致したときにルールが適用されます。ドメイン: example.com、domain:example.com、keyword:google、geosite:netflix。IP: 1.2.3.0/24、geoip:cn。"),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "id", "Aturan cocok bila semua kolom yang diisi cocok. Domain: example.com, domain:example.com, keyword:google, geosite:netflix. IP: 1.2.3.0/24, geoip:cn."),
        ("A rule matches when every filled-in field matches. Domains: example.com, domain:example.com, keyword:google, geosite:netflix. IPs: 1.2.3.0/24, geoip:cn.", "tr", "Doldurulan tüm alanlar eşleştiğinde kural uygulanır. Alan adları: example.com, domain:example.com, keyword:google, geosite:netflix. IP: 1.2.3.0/24, geoip:cn."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "ru", "Ваши правила ниже действуют при любом пресете: после обхода локальной сети и до страновых правил пресета."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "zh", "下面你自己的规则在任何预设下都会生效：排在局域网直连之后、预设的国家规则之前。"),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "es", "Tus reglas de abajo se aplican con cualquier preajuste: después del bypass de la LAN y antes de las reglas de país del preajuste."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "hi", "नीचे दिए आपके नियम हर प्रीसेट में चलते हैं — LAN bypass के बाद और प्रीसेट के देश-नियमों से पहले।"),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "ar", "قواعدك أدناه تعمل مع كل الإعدادات المسبقة: بعد تجاوز الشبكة المحلية وقبل قواعد الدول في الإعداد المسبق."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "fr", "Vos règles ci-dessous s'appliquent avec tous les préréglages : après le contournement du LAN et avant les règles pays du préréglage."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "pt", "Suas regras abaixo valem em todos os predefinidos: depois do bypass da LAN e antes das regras de país do predefinido."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "de", "Deine Regeln unten gelten bei jeder Voreinstellung: nach dem LAN-Bypass und vor den Länderregeln der Voreinstellung."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "ja", "下のユーザールールはどのプリセットでも有効です。LAN 直結の後、プリセットの国別ルールの前に評価されます。"),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "id", "Aturan Anda di bawah berlaku di semua preset: setelah bypass LAN dan sebelum aturan negara dari preset."),
        ("Your own rules below run under every preset, after the LAN bypass and before the preset's country rules.", "tr", "Aşağıdaki kendi kurallarınız her ön ayarda çalışır: LAN atlamasından sonra, ön ayarın ülke kurallarından önce."),
        ("Changes apply on the next connect or reconnect.", "ru", "Изменения применятся при следующем подключении или переподключении."),
        ("Changes apply on the next connect or reconnect.", "zh", "更改将在下次连接或重连时生效。"),
        ("Changes apply on the next connect or reconnect.", "es", "Los cambios se aplican en la próxima conexión o reconexión."),
        ("Changes apply on the next connect or reconnect.", "hi", "बदलाव अगली बार कनेक्ट या रीकनेक्ट करने पर लागू होंगे।"),
        ("Changes apply on the next connect or reconnect.", "ar", "تُطبَّق التغييرات عند الاتصال أو إعادة الاتصال التالي."),
        ("Changes apply on the next connect or reconnect.", "fr", "Les modifications s'appliquent à la prochaine connexion ou reconnexion."),
        ("Changes apply on the next connect or reconnect.", "pt", "As alterações entram em vigor na próxima conexão ou reconexão."),
        ("Changes apply on the next connect or reconnect.", "de", "Änderungen wirken beim nächsten Verbinden oder Neuverbinden."),
        ("Changes apply on the next connect or reconnect.", "ja", "変更は次回の接続または再接続で反映されます。"),
        ("Changes apply on the next connect or reconnect.", "id", "Perubahan berlaku pada koneksi atau sambungan ulang berikutnya."),
        ("Changes apply on the next connect or reconnect.", "tr", "Değişiklikler bir sonraki bağlanmada veya yeniden bağlanmada geçerli olur."),
        ("Used by the Xray core. The sing-box core downloads the matching rule-sets on its own.", "ru", "Используется ядром Xray. Ядро sing-box само скачивает соответствующие rule-set."),
        ("Used by the Xray core. The sing-box core downloads the matching rule-sets on its own.", "zh", "供 Xray 内核使用。sing-box 内核会自行下载对应的 rule-set。"),
        ("Used by the Xray core. The sing-box core downloads the matching rule-sets on its own.", "es", "Lo usa el núcleo Xray. El núcleo sing-box descarga por su cuenta los rule-sets correspondientes."),
        ("Used by the Xray core. The sing-box core downloads the matching rule-sets on its own.", "hi", "Xray core इसे उपयोग करता है। sing-box core संबंधित rule-set खुद डाउनलोड करता है।"),
        ("Used by the Xray core. The sing-box core downloads the matching rule-sets on its own.", "ar", "تستخدمها نواة Xray. أما نواة sing-box فتنزّل مجموعات القواعد المقابلة بنفسها."),
        ("Used by the Xray core. The sing-box core downloads the matching rule-sets on its own.", "fr", "Utilisé par le cœur Xray. Le cœur sing-box télécharge lui-même les rule-sets correspondants."),
        ("Used by the Xray core. The sing-box core downloads the matching rule-sets on its own.", "pt", "Usado pelo núcleo Xray. O núcleo sing-box baixa sozinho os rule-sets correspondentes."),
