        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "ru", "Группа ведёт себя как один сервер: выберите участника вручную или пусть победит самый быстрый."),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "zh", "分组的行为就像一个服务器：手动选择成员，或让最快的胜出。"),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "es", "Un grupo se comporta como un servidor: elige un miembro a mano o deja que gane el más rápido."),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "hi", "समूह एक सर्वर की तरह काम करता है: सदस्य खुद चुनें या सबसे तेज़ को जीतने दें।"),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "ar", "تتصرف المجموعة كخادم واحد: اختر عضوًا يدويًا أو دع الأسرع يفوز."),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "fr", "Un groupe se comporte comme un seul serveur : choisissez un membre à la main ou laissez le plus rapide gagner."),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "pt", "Um grupo funciona como um servidor: escolha um membro à mão ou deixe o mais rápido vencer."),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "de", "Eine Gruppe verhält sich wie ein Server: Mitglied selbst wählen oder das schnellste gewinnen lassen."),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "ja", "グループは 1 台のサーバーのように動きます。メンバーを手で選ぶか、最速のものに任せます。"),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "id", "Grup berperilaku seperti satu server: pilih anggota secara manual, atau biarkan yang tercepat menang."),
        ("A group behaves like one server: pick a member by hand, or let the fastest one win.", "tr", "Grup tek bir sunucu gibi davranır: üyeyi elle seçin ya da en hızlısı kazansın."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "ru", "Группы видны и в control API, поэтому панель — или ассистент — может сменить участника без перезапуска туннеля."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "zh", "分组也会出现在控制 API 中，面板或助手可以在不重启隧道的情况下切换成员。"),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "es", "Los grupos también aparecen en la API de control, así que un panel —o un asistente— puede cambiar de miembro sin reiniciar el túnel."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "hi", "समूह control API में भी दिखते हैं, इसलिए डैशबोर्ड — या कोई असिस्टेंट — टनल रीस्टार्ट किए बिना सदस्य बदल सकता है।"),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "ar", "تظهر المجموعات أيضًا في واجهة التحكم، فيمكن للوحة — أو لمساعد — تبديل العضو دون إعادة تشغيل النفق."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "fr", "Les groupes apparaissent aussi dans l'API de contrôle : un tableau de bord — ou un assistant — peut changer de membre sans redémarrer le tunnel."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "pt", "Os grupos também aparecem na API de controle, então um painel — ou um assistente — pode trocar o membro sem reiniciar o túnel."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "de", "Gruppen erscheinen auch in der Steuerungs-API, sodass ein Dashboard — oder ein Assistent — das Mitglied ohne Neustart des Tunnels wechseln kann."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "ja", "グループは制御 API にも現れるため、ダッシュボードやアシスタントがトンネルを再起動せずにメンバーを切り替えられます。"),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "id", "Grup juga muncul di control API, sehingga dasbor — atau asisten — bisa mengganti anggota tanpa memulai ulang terowongan."),
        ("Groups also show up in the control API, so a dashboard — or an assistant — can switch the member without restarting the tunnel.", "tr", "Gruplar kontrol API'sinde de görünür; bir panel — ya da bir asistan — tüneli yeniden başlatmadan üyeyi değiştirebilir."),
