        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "ru", "Мгновенно отвечает адресом из приватного диапазона и сохраняет домен видимым для правил. Ломает программы, которые резолвят имена сами."),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "zh", "用私有网段立即作答，并让规则仍能看到域名。会破坏自行解析域名的软件。"),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "es", "Responde al instante con un rango privado y mantiene el dominio visible para las reglas. Rompe el software que resuelve los nombres por su cuenta."),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "hi", "प्राइवेट रेंज से तुरंत उत्तर देता है और डोमेन नियमों को दिखता रहता है। जो सॉफ़्टवेयर खुद नाम रिज़ॉल्व करते हैं, वे टूट जाते हैं।"),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "ar", "يرد فورًا من نطاق خاص ويبقي اسم النطاق ظاهرًا للقواعد. يعطّل البرامج التي تحلّ الأسماء بنفسها."),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "fr", "Répond immédiatement depuis une plage privée et garde le domaine visible pour les règles. Casse les logiciels qui résolvent les noms eux-mêmes."),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "pt", "Responde na hora com uma faixa privada e mantém o domínio visível para as regras. Quebra programas que resolvem os nomes por conta própria."),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "de", "Antwortet sofort aus einem privaten Bereich und hält die Domain für Regeln sichtbar. Bricht Software, die Namen selbst auflöst."),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "ja", "プライベート範囲から即座に応答し、ドメインをルールから見えるままにします。自前で名前解決するソフトは動かなくなります。"),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "id", "Menjawab seketika dari rentang privat dan menjaga domain tetap terlihat oleh aturan. Merusak perangkat lunak yang meresolusi nama sendiri."),
        ("Answers instantly from a private range and keeps the domain visible to rules. Breaks software that resolves names itself.", "tr", "Özel bir aralıktan anında yanıt verir ve alan adını kurallara görünür tutar. Adları kendi çözen yazılımları bozar."),
        ("Add resolver", "ru", "Добавить резолвер"),
