        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "ru", "Те же условия, что и в правиле маршрутизации, кроме требующих адреса: имя ещё резолвится, IP назначения пока нет."),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "zh", "与路由规则相同的匹配条件，但不含需要地址的那些：此时正在解析域名，还没有目标 IP。"),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "es", "Los mismos criterios que en una regla de enrutamiento, salvo los que necesitan una dirección: se está resolviendo un nombre, así que aún no hay IP de destino."),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "hi", "रूटिंग नियम जैसे ही मैचर, सिवाय उनके जिन्हें पता चाहिए: अभी नाम रिज़ॉल्व हो रहा है, इसलिए गंतव्य IP नहीं है।"),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "ar", "نفس شروط قاعدة التوجيه، باستثناء ما يحتاج إلى عنوان: الاسم قيد التحليل، فلا يوجد عنوان وجهة بعد."),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "fr", "Les mêmes critères qu'une règle de routage, sauf ceux qui exigent une adresse : un nom est en cours de résolution, il n'y a pas encore d'IP de destination."),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "pt", "Os mesmos critérios de uma regra de roteamento, menos os que exigem endereço: um nome está sendo resolvido, então ainda não há IP de destino."),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "de", "Dieselben Kriterien wie bei einer Routing-Regel, ohne die, die eine Adresse brauchen: Ein Name wird gerade aufgelöst, eine Ziel-IP gibt es noch nicht."),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "ja", "ルーティングルールと同じ条件から、アドレスを必要とするものを除いたものです。名前を解決中なので、宛先 IP はまだありません。"),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "id", "Pencocok yang sama seperti aturan perutean, tanpa yang memerlukan alamat: sebuah nama sedang diresolusi, jadi belum ada IP tujuan."),
        ("Same matchers as a routing rule, minus the ones that need an address: a name is being resolved, so there is no destination IP yet.", "tr", "Yönlendirme kuralıyla aynı ölçütler, adres gerektirenler hariç: bir ad çözülüyor, bu yüzden henüz hedef IP yok."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "ru", "Используется ядром sing-box. Ядро Xray берёт простой список серверов из настроек."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "zh", "供 sing-box 内核使用。Xray 路径使用设置中的普通服务器列表。"),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "es", "Lo usa el núcleo sing-box. La vía Xray usa la lista simple de servidores de Ajustes."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "hi", "sing-box core इसे उपयोग करता है। Xray पथ Settings की सादा सर्वर सूची लेता है।"),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "ar", "تستخدمه نواة sing-box. أما مسار Xray فيستخدم قائمة الخوادم البسيطة في الإعدادات."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "fr", "Utilisé par le cœur sing-box. La voie Xray utilise la liste de serveurs simple des réglages."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "pt", "Usado pelo núcleo sing-box. O caminho Xray usa a lista simples de servidores nas Configurações."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "de", "Wird vom sing-box-Kern genutzt. Der Xray-Weg verwendet die einfache Serverliste in den Einstellungen."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "ja", "sing-box コアが使用します。Xray 経路は設定の単純なサーバー一覧を使います。"),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "id", "Dipakai core sing-box. Jalur Xray memakai daftar server sederhana di Pengaturan."),
        ("Used by the sing-box core. The Xray path uses the plain server list in Settings.", "tr", "sing-box çekirdeği kullanır. Xray yolu Ayarlar'daki düz sunucu listesini kullanır."),
