        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "ru", "sing-box сам ведёт туннель — именно это позволяет правилу совпадать с приложением. Отключите, чтобы вернуться к tun2socks."),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "zh", "sing-box 亲自处理隧道，规则才能匹配到应用。关闭后会退回 tun2socks。"),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "es", "sing-box gestiona el túnel por sí mismo, que es lo que permite que una regla coincida con una aplicación. Desactívalo para volver a tun2socks."),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "hi", "sing-box खुद टनल संभालता है, इसी से नियम किसी ऐप से मेल खा पाता है। बंद करने पर tun2socks पर लौट आएँगे।"),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "ar", "تتولى sing-box النفق بنفسها، وهذا ما يسمح للقاعدة بمطابقة تطبيق. أوقفه للعودة إلى tun2socks."),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "fr", "sing-box gère le tunnel lui-même, ce qui permet à une règle de correspondre à une application. Désactivez pour revenir à tun2socks."),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "pt", "O sing-box cuida do túnel sozinho, e é isso que permite uma regra corresponder a um aplicativo. Desative para voltar ao tun2socks."),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "de", "sing-box führt den Tunnel selbst — nur so kann eine Regel ein Programm treffen. Ausschalten, um zu tun2socks zurückzukehren."),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "ja", "sing-box が自らトンネルを扱うため、ルールがアプリに一致できます。オフにすると tun2socks に戻ります。"),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "id", "sing-box menangani terowongan sendiri, dan itulah yang membuat aturan bisa cocok dengan aplikasi. Matikan untuk kembali ke tun2socks."),
        ("sing-box handles the tunnel itself, which is what lets a rule match an application. Turn this off to fall back to tun2socks.", "tr", "Tüneli sing-box kendisi yönetir; bir kuralın uygulamayla eşleşmesini sağlayan budur. Kapatınca tun2socks'a dönülür."),
