        ("Stops traffic from leaving around the tunnel. Can break local network access.", "ru", "Не даёт трафику уходить мимо туннеля. Может сломать доступ к локальной сети."),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "zh", "阻止流量绕过隧道。可能会影响局域网访问。"),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "es", "Impide que el tráfico salga por fuera del túnel. Puede romper el acceso a la red local."),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "hi", "ट्रैफ़िक को टनल के बाहर जाने से रोकता है। लोकल नेटवर्क एक्सेस टूट सकता है।"),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "ar", "يمنع مرور البيانات خارج النفق. قد يعطّل الوصول إلى الشبكة المحلية."),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "fr", "Empêche le trafic de sortir en dehors du tunnel. Peut casser l'accès au réseau local."),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "pt", "Impede que o tráfego saia por fora do túnel. Pode quebrar o acesso à rede local."),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "de", "Verhindert, dass Verkehr am Tunnel vorbeigeht. Kann den Zugriff aufs lokale Netz brechen."),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "ja", "トンネルを迂回する通信を止めます。ローカルネットワークへのアクセスが壊れることがあります。"),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "id", "Mencegah trafik keluar di luar terowongan. Bisa merusak akses jaringan lokal."),
        ("Stops traffic from leaving around the tunnel. Can break local network access.", "tr", "Trafiğin tünelin dışından çıkmasını engeller. Yerel ağ erişimini bozabilir."),
