        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "ru", "Отдаётся ядром, пока есть подключение, — для панелей вроде Yacd. Его секрет меняется при каждом запуске."),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "zh", "连接期间由内核提供，供 Yacd 等面板使用。其密钥每次启动都会更换。"),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "es", "Lo sirve el núcleo mientras hay conexión, para paneles como Yacd. Su secreto cambia en cada arranque."),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "hi", "कनेक्ट रहते हुए core इसे देता है, Yacd जैसे डैशबोर्ड के लिए। इसका सीक्रेट हर लॉन्च पर बदलता है।"),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "ar", "تقدّمه النواة أثناء الاتصال، للوحات مثل Yacd. يتغيّر سرّه في كل تشغيل."),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "fr", "Servie par le cœur pendant la connexion, pour des tableaux de bord comme Yacd. Son secret change à chaque lancement."),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "pt", "Servida pelo núcleo enquanto conectado, para painéis como o Yacd. O segredo muda a cada inicialização."),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "de", "Wird vom Kern während der Verbindung bereitgestellt, für Dashboards wie Yacd. Sein Geheimnis wechselt bei jedem Start."),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "ja", "接続中にコアが提供します。Yacd などのダッシュボード用で、シークレットは起動ごとに変わります。"),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "id", "Disajikan core selama terhubung, untuk dasbor seperti Yacd. Rahasianya berubah setiap peluncuran."),
        ("Served by the core while connected, for dashboards like Yacd. Its secret changes on every launch.", "tr", "Bağlıyken çekirdek tarafından sunulur, Yacd gibi paneller için. Parolası her açılışta değişir."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "ru", "Слушает только 127.0.0.1 и требует токен. Кто владеет токеном — может менять маршруты вашего трафика."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "zh", "仅监听 127.0.0.1 并需要令牌。持有令牌的一方可以改变你的流量走向。"),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "es", "Escucha solo en 127.0.0.1 y exige el token. Quien lo tenga puede cambiar por dónde sale tu tráfico."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "hi", "केवल 127.0.0.1 पर सुनता है और टोकन माँगता है। जिसके पास टोकन है, वह आपके ट्रैफ़िक का रास्ता बदल सकता है।"),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "ar", "يستمع على 127.0.0.1 فقط ويتطلب الرمز. من يملكه يستطيع تغيير مسار بياناتك."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "fr", "N'écoute que sur 127.0.0.1 et exige le jeton. Quiconque le détient peut changer le chemin de votre trafic."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "pt", "Escuta apenas em 127.0.0.1 e exige o token. Quem o tiver pode mudar por onde seu tráfego sai."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "de", "Hört nur auf 127.0.0.1 und verlangt das Token. Wer es hat, kann ändern, wohin dein Verkehr geht."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "ja", "127.0.0.1 のみで待ち受け、トークンを要求します。トークンを持つ相手は通信の経路を変更できます。"),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "id", "Hanya mendengarkan di 127.0.0.1 dan memerlukan token. Siapa pun yang memegangnya bisa mengubah ke mana trafik Anda pergi."),
        ("Listens on 127.0.0.1 only and needs the token. Anything holding it can change where your traffic goes.", "tr", "Yalnızca 127.0.0.1 üzerinde dinler ve belirteç ister. Belirteci elinde tutan, trafiğinizin nereden geçtiğini değiştirebilir."),
