        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "hi", "कोई एक चुनें और पूरी सेवा — Telegram, YouTube, Discord — बिना डोमेन लिखे रूट करें।"),
        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "ar", "اختر قائمة لتوجيه خدمة كاملة — Telegram أو YouTube أو Discord — دون كتابة نطاقاتها يدويًا."),
        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "fr", "Choisissez-en une pour router un service entier — Telegram, YouTube, Discord — sans écrire ses domaines à la main."),
        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "pt", "Escolha uma para rotear um serviço inteiro — Telegram, YouTube, Discord — sem escrever os domínios à mão."),
        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "de", "Eine auswählen, um einen ganzen Dienst — Telegram, YouTube, Discord — zu routen, ohne Domains abzutippen."),
        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "ja", "1 つ選ぶだけで、Telegram・YouTube・Discord などのサービス全体をドメインを書かずに振り分けられます。"),
        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "id", "Pilih satu untuk merutekan seluruh layanan — Telegram, YouTube, Discord — tanpa menulis domainnya satu per satu."),
        ("Pick one to route a whole service — Telegram, YouTube, Discord — without writing its domains out by hand.", "tr", "Birini seçerek Telegram, YouTube, Discord gibi bir servisin tamamını alan adlarını tek tek yazmadan yönlendirin."),
