        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "ru", "Готовые списки доменов и подсетей из проекта allow-domains. Выбранный список добавляет правило, которое ловит всё из него."),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "zh", "来自 allow-domains 项目的现成域名与子网列表。选中后会添加一条匹配其中全部条目的规则。"),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "es", "Listas de dominios y subredes ya hechas del proyecto allow-domains. Al elegir una se añade una regla que coincide con todo su contenido."),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "hi", "allow-domains परियोजना की तैयार डोमेन और सबनेट सूचियाँ। कोई चुनने पर एक नियम जुड़ता है जो उसकी सारी प्रविष्टियों से मेल खाता है।"),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "ar", "قوائم نطاقات وشبكات فرعية جاهزة من مشروع allow-domains. اختيار قائمة يضيف قاعدة تطابق كل ما فيها."),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "fr", "Listes de domaines et de sous-réseaux toutes faites du projet allow-domains. En choisir une ajoute une règle qui correspond à tout son contenu."),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "pt", "Listas prontas de domínios e sub-redes do projeto allow-domains. Escolher uma adiciona uma regra que corresponde a tudo nela."),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "de", "Fertige Domain- und Subnetzlisten aus dem Projekt allow-domains. Eine Auswahl fügt eine Regel hinzu, die alles darin trifft."),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "ja", "allow-domains プロジェクトが公開しているドメインとサブネットの既製リストです。選ぶと、その全項目に一致するルールが追加されます。"),
        ("Ready-made domain and subnet lists from the allow-domains project. Picking one adds a rule that matches everything in it.", "id", "Daftar domain dan subnet siap pakai dari proyek allow-domains. Memilih satu akan menambah aturan yang cocok dengan seluruh isinya."),
