        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "ru", "Установленный хелпер привязан к прежней сборке Veil и не принимает текущую, поэтому TUN не запускается."),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "zh", "已安装的助手绑定到旧版本的 Veil，拒绝当前版本，因此 TUN 无法启动。"),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "es", "El asistente instalado está ligado a una compilación anterior de Veil y rechaza esta, así que TUN no puede iniciarse."),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "hi", "इंस्टॉल हेल्पर Veil के पुराने बिल्ड से बंधा है और इसे स्वीकार नहीं करता, इसलिए TUN शुरू नहीं हो सकता।"),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "ar", "المساعد المثبَّت مرتبط بإصدار أقدم من Veil ويرفض هذا الإصدار، لذا لا يمكن تشغيل TUN."),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "fr", "L'assistant installé est lié à une version antérieure de Veil et refuse celle-ci, donc TUN ne peut pas démarrer."),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "pt", "O auxiliar instalado está vinculado a uma versão anterior do Veil e recusa esta, então o TUN não inicia."),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "de", "Der installierte Hilfsdienst ist an einen älteren Veil-Build gebunden und lehnt diesen ab, daher startet TUN nicht."),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "ja", "インストール済みのヘルパーは以前のビルドに固定されており、現在のビルドを拒否するため TUN を開始できません。"),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "id", "Helper yang terpasang terikat ke build Veil lama dan menolak yang ini, jadi TUN tidak bisa dijalankan."),
        ("The installed helper was pinned to an older build of Veil and refuses this one, so TUN cannot start.", "tr", "Kurulu yardımcı, Veil'in eski bir derlemesine sabitlenmiş ve bunu reddediyor, bu yüzden TUN başlatılamıyor."),
