        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "ru", "Если выключено, имена разрешает резолвер вашей сети — соединение идёт через туннель, но домен, который этот резолвер блокирует или подменяет, так и не откроется."),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "zh", "关闭后，域名由所在网络的解析器解析——连接仍走隧道，但被该解析器屏蔽或污染的域名依旧打不开。"),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "es", "Con esto desactivado, los nombres los resuelve el resolutor de tu red: el túnel transporta la conexión, pero un dominio que ese resolutor bloquea o envenena sigue sin funcionar."),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "hi", "यह बंद होने पर नाम आपके नेटवर्क का ही रिज़ॉल्वर हल करता है — कनेक्शन टनल से जाता है, पर जिस डोमेन को वह रिज़ॉल्वर ब्लॉक या ख़राब करता है वह टूटा ही रहता है।"),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "ar", "عند إيقاف هذا، يتولى محلل أسماء شبكتك الاستعلامات — يمر الاتصال عبر النفق، لكن النطاق الذي يحجبه ذلك المحلل أو يزيّفه يظل معطلاً."),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "fr", "Désactivé, les noms sont résolus par le résolveur de votre réseau : le tunnel transporte la connexion, mais un domaine que ce résolveur bloque ou empoisonne reste inaccessible."),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "pt", "Com isto desligado, os nomes são resolvidos pelo resolvedor da sua rede: o túnel transporta a ligação, mas um domínio que esse resolvedor bloqueia ou envenena continua quebrado."),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "de", "Ist das aus, löst der Resolver deines Netzwerks die Namen auf — der Tunnel trägt die Verbindung, aber eine Domain, die dieser Resolver blockiert oder verfälscht, bleibt kaputt."),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "ja", "これをオフにすると、名前解決はネットワーク側のリゾルバが行います。接続はトンネルを通りますが、そのリゾルバがブロックまたは改ざんするドメインは開けないままです。"),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "id", "Jika ini mati, nama diselesaikan oleh resolver jaringan Anda — koneksi tetap lewat terowongan, tetapi domain yang diblokir atau diracuni resolver itu tetap tidak terbuka."),
        ("With this off, names are resolved by your network's own resolver — the tunnel carries the connection, but a domain that resolver blocks or poisons stays broken.", "tr", "Bu kapalıyken adları ağınızın kendi çözümleyicisi çözer — bağlantı tünelden geçer, ama o çözümleyicinin engellediği veya zehirlediği alan adı yine açılmaz."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "ru", "Стартовый резолвер работает до того, как туннель поднят, поэтому его запросы всегда идут напрямую."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "zh", "引导解析器在隧道建立之前工作，因此它自己的查询始终走直连。"),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "es", "El resolutor de arranque funciona antes de que exista el túnel, por eso sus consultas siempre van directas."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "hi", "बूटस्ट्रैप रिज़ॉल्वर टनल बनने से पहले चलता है, इसलिए उसकी क्वेरी हमेशा सीधे जाती हैं।"),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "ar", "يعمل محلل الإقلاع قبل وجود النفق، لذلك تذهب استعلاماته دائمًا مباشرة."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "fr", "Le résolveur d'amorçage fonctionne avant que le tunnel existe : ses requêtes passent donc toujours en direct."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "pt", "O resolvedor de arranque funciona antes de o túnel existir, por isso as suas consultas vão sempre diretas."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "de", "Der Bootstrap-Resolver läuft, bevor der Tunnel existiert — seine Anfragen gehen deshalb immer direkt."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "ja", "ブートストラップ用リゾルバはトンネルができる前に動くため、その問い合わせは常に直接送られます。"),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "id", "Resolver bootstrap bekerja sebelum terowongan ada, jadi kuerinya selalu langsung."),
        ("The bootstrap resolver runs before the tunnel exists, so its own queries always go direct.", "tr", "Önyükleme çözümleyicisi tünel var olmadan önce çalışır, bu yüzden sorguları her zaman doğrudan gider."),
