        ("Shown instead of the name the source gives this server.", "ru", "Показывается вместо имени, которое даёт источник."),
        ("Shown instead of the name the source gives this server.", "zh", "用于替代来源给这台服务器的名称。"),
        ("Shown instead of the name the source gives this server.", "es", "Se muestra en lugar del nombre que le da la fuente."),
        ("Shown instead of the name the source gives this server.", "hi", "स्रोत द्वारा दिए गए नाम के बजाय दिखाया जाता है।"),
        ("Shown instead of the name the source gives this server.", "ar", "يظهر بدلاً من الاسم الذي يمنحه المصدر لهذا الخادم."),
        ("Shown instead of the name the source gives this server.", "fr", "Affiché à la place du nom donné par la source."),
        ("Shown instead of the name the source gives this server.", "pt", "Mostrado em vez do nome que a fonte dá a este servidor."),
        ("Shown instead of the name the source gives this server.", "de", "Wird anstelle des Namens angezeigt, den die Quelle vergibt."),
        ("Shown instead of the name the source gives this server.", "ja", "提供元が付けた名前の代わりに表示されます。"),
        ("Shown instead of the name the source gives this server.", "id", "Ditampilkan menggantikan nama dari sumbernya."),
        ("Shown instead of the name the source gives this server.", "tr", "Kaynağın verdiği adın yerine gösterilir."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "ru", "Раскладывает список по подпискам, тегам или странам. Теги и страны объединяют все подписки в один список."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "zh", "按订阅、标签或国家/地区排列列表。标签和国家/地区会把所有订阅合并为一个列表。"),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "es", "Ordena la lista por suscripción, por etiqueta o por país. Las etiquetas y los países fusionan todas las suscripciones en una sola lista."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "hi", "सूची को सदस्यता, टैग या देश के अनुसार व्यवस्थित करें। टैग और देश सभी सदस्यताओं को एक सूची में मिला देते हैं।"),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "ar", "رتّب القائمة حسب الاشتراك أو الوسم أو الدولة. الوسوم والدول تدمج كل الاشتراكات في قائمة واحدة."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "fr", "Classe la liste par abonnement, par étiquette ou par pays. Les étiquettes et les pays fusionnent tous les abonnements en une seule liste."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "pt", "Organiza a lista por assinatura, por etiqueta ou por país. As etiquetas e os países juntam todas as assinaturas numa só lista."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "de", "Ordnet die Liste nach Abo, Tag oder Land. Tags und Länder führen alle Abos zu einer Liste zusammen."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "ja", "リストをサブスクリプション、タグ、国のいずれかで並べます。タグと国ではすべてのサブスクリプションが 1 つのリストにまとまります。"),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "id", "Susun daftar berdasarkan langganan, tag, atau negara. Tag dan negara menggabungkan semua langganan menjadi satu daftar."),
        ("Arrange the list by subscription, by tag, or by country. Tags and countries merge every subscription into one list.", "tr", "Listeyi aboneliğe, etikete veya ülkeye göre düzenler. Etiket ve ülke, tüm abonelikleri tek listede birleştirir."),
