        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "ru", "Серверы подписки принадлежат панели. Переименовать, пометить тегом, закрепить — это ваше и переживает обновление, но чтобы изменить параметры подключения, скопируйте сервер в «Свои»."),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "zh", "订阅中的服务器属于面板。重命名、打标签、置顶都是你的设置，更新后仍然保留；但要修改连接参数，请把它复制到「手动」。"),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "es", "Los servidores de una suscripción son del panel. Renombrarlos, etiquetarlos y fijarlos es tuyo y sobrevive a una actualización; para cambiar a qué se conectan, duplícalos en Manual."),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "hi", "सदस्यता के सर्वर पैनल के होते हैं। नाम बदलना, टैग करना, पिन करना आपका है और रीफ़्रेश के बाद भी रहता है — पर कनेक्शन बदलने के लिए उसे Manual में डुप्लिकेट करें।"),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "ar", "خوادم الاشتراك تخص اللوحة. إعادة التسمية والوسم والتثبيت ملكك وتبقى بعد التحديث، أما لتغيير ما يتصل به الخادم فانسخه إلى «يدوي»."),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "fr", "Les serveurs d’un abonnement appartiennent au panneau. Les renommer, les étiqueter, les épingler vous appartient et survit à une actualisation ; pour changer ce à quoi ils se connectent, dupliquez-les dans Manuel."),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "pt", "Os servidores de uma assinatura são do painel. Renomear, etiquetar e fixar é seu e sobrevive a uma atualização; para mudar aquilo a que um servidor se liga, duplique-o em Manual."),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "de", "Die Server eines Abos gehören dem Panel. Umbenennen, markieren und anheften gehört Ihnen und übersteht eine Aktualisierung; um zu ändern, wohin ein Server verbindet, duplizieren Sie ihn nach Manuell."),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "ja", "サブスクリプションのサーバーはパネルのものです。名前・タグ・ピン留めはあなたの設定で更新後も残りますが、接続先を変えるには「手動」に複製してください。"),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "id", "Server dalam langganan milik panel. Mengganti nama, memberi tag, dan menyematkan adalah milik Anda dan bertahan setelah pembaruan; untuk mengubah tujuan koneksinya, gandakan ke Manual."),
        ("A subscription's servers are the panel's. Rename them, tag them, pin them — that is yours and survives a refresh — but to change what one connects to, duplicate it into Manual.", "tr", "Aboneliğin sunucuları panele aittir. Yeniden adlandırma, etiketleme ve sabitleme sizindir ve yenilemeden sonra kalır; bağlandığı yeri değiştirmek için sunucuyu Manuel’e çoğaltın."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "ru", "Копирует сервер в «Свои», где его можно менять. Копия подписки не затрагивается."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "zh", "把这台服务器复制到「手动」，在那里可以修改。订阅自己的副本不受影响。"),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "es", "Copia este servidor en Manual, donde se puede modificar. La copia de la suscripción no se toca."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "hi", "इस सर्वर को Manual में कॉपी करता है, जहाँ इसे बदला जा सकता है। सदस्यता की अपनी प्रति अछूती रहती है।"),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "ar", "ينسخ هذا الخادم إلى «يدوي» حيث يمكن تعديله، وتبقى نسخة الاشتراك كما هي."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "fr", "Copie ce serveur dans Manuel, où il peut être modifié. La copie de l’abonnement reste intacte."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "pt", "Copia este servidor para Manual, onde pode ser alterado. A cópia da assinatura fica intacta."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "de", "Kopiert diesen Server nach Manuell, wo er geändert werden kann. Die Kopie des Abos bleibt unberührt."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "ja", "このサーバーを「手動」に複製します。そこでは編集でき、サブスクリプション側の元は変わりません。"),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "id", "Menyalin server ini ke Manual, tempat ia bisa diubah. Salinan langganan tidak tersentuh."),
        ("Copies this server into Manual, where it can be changed. The subscription's own copy is left alone.", "tr", "Bu sunucuyu, değiştirilebildiği Manuel’e kopyalar. Aboneliğin kendi kopyasına dokunulmaz."),
