        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "ru", "Эти записи были отброшены при чтении источника. Сервер, которого нет в списке, указан здесь с причиной."),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "zh", "读取来源时丢弃了这些条目。列表中缺少的服务器会连同原因列在这里。"),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "es", "Estas entradas se descartaron al leer la fuente. Un servidor que falta en la lista aparece aquí con el motivo."),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "hi", "स्रोत पढ़ते समय ये प्रविष्टियाँ छोड़ दी गईं। सूची से गायब सर्वर यहाँ कारण सहित दिखाया गया है।"),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "ar", "تم تجاهل هذه المدخلات أثناء قراءة المصدر. الخادم الغائب عن القائمة مذكور هنا مع السبب."),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "fr", "Ces entrées ont été ignorées lors de la lecture de la source. Un serveur absent de la liste est indiqué ici avec la raison."),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "pt", "Estas entradas foram descartadas ao ler a fonte. Um servidor ausente da lista aparece aqui com o motivo."),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "de", "Diese Einträge wurden beim Lesen der Quelle verworfen. Ein Server, der in der Liste fehlt, steht hier mit dem Grund."),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "ja", "ソースの読み取り時にこれらの項目は破棄されました。一覧にないサーバーは理由とともにここに表示されます。"),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "id", "Entri ini diabaikan saat membaca sumber. Server yang hilang dari daftar dicantumkan di sini beserta alasannya."),
        ("These entries were dropped while reading the source. A server that is missing from the list is listed here with the reason.", "tr", "Kaynak okunurken bu girdiler atlandı. Listede olmayan bir sunucu nedeniyle birlikte burada listelenir."),
