        ("What this preset does", "tr", "Bu ön ayar ne yapar"),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "ru", "Этим правилам нужен собственный туннель sing-box. Если он выключен, в режиме TUN есть только один исходящий прокси, и правило, указывающее на сервер или группу, отправит трафик через прокси по умолчанию."),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "zh", "这些规则需要 sing-box 自带的隧道。关闭后，TUN 模式只有一个代理出站，因此指向某个服务器或组的规则会改走默认出站。"),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "es", "Estas reglas necesitan el propio túnel de sing-box. Con él desactivado, el modo TUN tiene una sola salida proxy, así que una regla que nombre un servidor o un grupo envía su tráfico por la predeterminada."),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "hi", "इन नियमों को sing-box की अपनी टनल चाहिए। इसे बंद रखने पर TUN मोड में केवल एक प्रॉक्सी आउटबाउंड होता है, इसलिए किसी सर्वर या समूह को नाम देने वाला नियम अपना ट्रैफ़िक डिफ़ॉल्ट से भेजता है।"),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "ar", "تحتاج هذه القواعد إلى نفق sing-box نفسه. وعند إيقافه، يكون لوضع TUN منفذ وكيل واحد فقط، لذا فإن أي قاعدة تسمّي خادمًا أو مجموعة ترسل حركتها عبر الوكيل الافتراضي."),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "fr", "Ces règles nécessitent le tunnel propre à sing-box. Sans lui, le mode TUN n'a qu'une seule sortie proxy, et une règle désignant un serveur ou un groupe envoie son trafic par la sortie par défaut."),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "pt", "Estas regras precisam do túnel do próprio sing-box. Com ele desligado, o modo TUN tem uma única saída proxy, então uma regra que nomeia um servidor ou grupo envia o tráfego pela padrão."),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "de", "Diese Regeln brauchen den eigenen Tunnel von sing-box. Ist er aus, hat der TUN-Modus nur einen Proxy-Ausgang, und eine Regel, die einen Server oder eine Gruppe nennt, schickt ihren Verkehr über den Standardausgang."),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "ja", "これらのルールには sing-box 自身のトンネルが必要です。オフの場合、TUN モードのプロキシ出口は 1 つだけなので、サーバーやグループを指定したルールは既定の出口を通ります。"),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "id", "Aturan ini membutuhkan tunnel milik sing-box. Jika dimatikan, mode TUN hanya punya satu outbound proxy, sehingga aturan yang menyebut server atau grup mengirim trafiknya lewat yang default."),
        ("These rules need sing-box's own tunnel. With it off, TUN mode has a single proxy outbound, so a rule naming a server or a group sends its traffic through the default one instead.", "tr", "Bu kurallar sing-box'ın kendi tünelini gerektirir. Kapalıyken TUN modunun tek bir proxy çıkışı olur, bu yüzden bir sunucu veya grup belirten kural trafiğini varsayılan çıkıştan gönderir."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "ru", "В текущей конфигурации эта цель не собирается, поэтому правило отправляет трафик через прокси по умолчанию."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "zh", "当前配置不会构建该目标，因此该规则会走默认代理。"),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "es", "Este destino no se construye en la configuración actual, así que la regla envía su tráfico por el proxy predeterminado."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "hi", "मौजूदा सेटअप में यह लक्ष्य नहीं बनता, इसलिए नियम अपना ट्रैफ़िक डिफ़ॉल्ट प्रॉक्सी से भेजता है।"),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "ar", "لا يُبنى هذا الهدف في الإعداد الحالي، لذا ترسل القاعدة حركتها عبر الوكيل الافتراضي."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "fr", "Cette cible n'est pas construite dans la configuration actuelle : la règle envoie donc son trafic par le proxy par défaut."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "pt", "Este destino não é construído na configuração atual, por isso a regra envia o tráfego pelo proxy padrão."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "de", "Dieses Ziel wird in der aktuellen Konfiguration nicht gebaut, daher schickt die Regel ihren Verkehr über den Standard-Proxy."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "ja", "現在の構成ではこの宛先が作られないため、ルールは既定のプロキシを通ります。"),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "id", "Target ini tidak dibangun pada konfigurasi saat ini, jadi aturan mengirim trafiknya lewat proxy default."),
        ("This target is not built in the current setup, so the rule sends its traffic through the default proxy.", "tr", "Bu hedef mevcut kurulumda oluşturulmuyor, bu yüzden kural trafiğini varsayılan proxy üzerinden gönderir."),
