        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "ru", "Они берутся из имени сервера и его настроек. Фильтруют и группируют как любые теги и меняются вместе с именем."),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "zh", "它们来自服务器自身的名称和设置。像普通标签一样用于筛选和分组，并随名称一起变化。"),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "es", "Provienen del propio nombre del servidor y de su configuración. Filtran y agrupan como cualquier etiqueta y cambian cuando cambia el nombre."),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "hi", "ये सर्वर के अपने नाम और उसकी सेटिंग्स से आते हैं। ये किसी भी टैग की तरह फ़िल्टर और समूह बनाते हैं और नाम बदलने पर बदल जाते हैं।"),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "ar", "تأتي من اسم الخادم نفسه ومن إعداداته. تُرشِّح وتُجمِّع مثل أي وسم، وتتغيّر عند تغيّر الاسم."),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "fr", "Elles proviennent du nom du serveur et de ses réglages. Elles filtrent et regroupent comme n'importe quelle étiquette et changent avec le nom."),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "pt", "Vêm do próprio nome do servidor e das suas definições. Filtram e agrupam como qualquer etiqueta e mudam quando o nome muda."),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "de", "Sie stammen aus dem Namen des Servers und seinen Einstellungen. Sie filtern und gruppieren wie jedes Tag und ändern sich mit dem Namen."),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "ja", "サーバー自身の名前と設定から得られます。通常のタグと同じく絞り込みとグループ化に使え、名前が変われば変わります。"),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "id", "Ini berasal dari nama server sendiri dan pengaturannya. Tag ini memfilter dan mengelompokkan seperti tag lain, dan berubah saat namanya berubah."),
        ("These come from the server's own name and its settings. They filter and group like any tag, and change when the name does.", "tr", "Bunlar sunucunun kendi adından ve ayarlarından gelir. Herhangi bir etiket gibi süzer ve gruplar, ad değiştiğinde değişir."),
