        ("What this means", "id", "Apa artinya ini"),
        ("What this means", "tr", "Bu ne anlama geliyor"),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "ru", "System Proxy указывает macOS на локальные порты Veil, поэтому маршрутизируются только приложения, читающие системный прокси: Telegram, терминал и всё через UDP — нет. TUN вместо этого забирает сетевой интерфейс, и через него идёт всё на этом Mac."),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "zh", "System Proxy 让 macOS 指向 Veil 的本地端口，因此只有读取系统代理的应用会被代理——Telegram、终端以及任何 UDP 流量都不会。TUN 则接管一个网络接口，这台 Mac 上的所有流量都会经过它。"),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "es", "System Proxy apunta macOS a los puertos locales de Veil, así que solo se enrutan las apps que leen el proxy del sistema: Telegram, la terminal y todo lo que va por UDP no. TUN, en cambio, toma una interfaz de red y todo el Mac pasa por ella."),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "hi", "System Proxy macOS को Veil के लोकल पोर्ट पर भेजता है, इसलिए केवल वही ऐप रूट होते हैं जो सिस्टम प्रॉक्सी पढ़ते हैं — Telegram, टर्मिनल और UDP वाला कुछ भी नहीं। TUN इसके बजाय एक नेटवर्क इंटरफ़ेस ले लेता है और इस Mac का सारा ट्रैफ़िक उससे गुज़रता है।"),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "ar", "يوجّه System Proxy نظام macOS إلى منافذ Veil المحلية، لذا لا يُوجَّه سوى التطبيقات التي تقرأ وكيل النظام — أمّا Telegram والطرفية وكل ما يمر عبر UDP فلا. أمّا TUN فيستولي على واجهة شبكة، فيمر عبرها كل شيء على هذا الـ Mac."),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "fr", "System Proxy pointe macOS vers les ports locaux de Veil : seules les apps qui lisent le proxy système sont routées — Telegram, le terminal et tout ce qui passe en UDP ne le sont pas. TUN prend à la place une interface réseau, et tout le Mac y passe."),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "pt", "O System Proxy aponta o macOS para as portas locais do Veil, por isso só são encaminhadas as apps que leem o proxy do sistema — o Telegram, o terminal e tudo o que use UDP não são. O TUN assume antes uma interface de rede e tudo neste Mac passa por ela."),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "de", "System Proxy richtet macOS auf Veils lokale Ports aus, also werden nur Apps geleitet, die den System-Proxy lesen — Telegram, das Terminal und alles über UDP nicht. TUN übernimmt stattdessen eine Netzwerkschnittstelle, und alles auf diesem Mac läuft darüber."),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "ja", "System Proxy は macOS を Veil のローカルポートに向けるため、システムプロキシを読むアプリだけが経由します。Telegram やターミナル、UDP の通信は経由しません。TUN はネットワークインターフェースを引き受けるので、この Mac のすべてがそこを通ります。"),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "id", "System Proxy mengarahkan macOS ke port lokal Veil, jadi hanya aplikasi yang membaca proxy sistem yang dirutekan — Telegram, terminal, dan apa pun lewat UDP tidak. TUN justru mengambil alih antarmuka jaringan, dan semua di Mac ini melewatinya."),
        ("System Proxy points macOS at Veil's local ports, so only apps that read the system proxy are routed — Telegram, the terminal and anything over UDP are not. TUN takes over a network interface instead, and everything on this Mac goes through it.", "tr", "System Proxy, macOS'u Veil'in yerel portlarına yönlendirir; bu yüzden yalnızca sistem vekilini okuyan uygulamalar yönlendirilir — Telegram, terminal ve UDP üzerinden giden hiçbir şey değil. TUN ise bir ağ arayüzünü devralır ve bu Mac'teki her şey oradan geçer."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "ru", "Как туннель передаёт пакеты. Оставьте автоматический выбор: стек mixed в sing-box уже убивал здесь все TCP-соединения, пока приложение продолжало показывать исправный туннель."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "zh", "隧道如何传输数据包。请保持自动：sing-box 的 mixed 栈曾在这里让所有 TCP 连接失效，而应用仍显示隧道正常。"),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "es", "Cómo mueve los paquetes el túnel. Déjalo en automático: la pila mixed de sing-box ha matado aquí todas las conexiones TCP mientras la app seguía indicando un túnel sano."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "hi", "टनल पैकेट कैसे भेजता है। इसे स्वचालित ही रहने दें: sing-box का mixed स्टैक यहाँ हर TCP कनेक्शन बंद कर चुका है, जबकि ऐप टनल को ठीक दिखाता रहा।"),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "ar", "كيف ينقل النفق الحِزم. اتركه تلقائيًا: فقد أوقفت طبقة mixed في sing-box كل اتصالات TCP هنا بينما ظل التطبيق يعرض نفقًا سليمًا."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "fr", "Comment le tunnel achemine les paquets. Laissez en automatique : la pile mixed de sing-box a ici tué toutes les connexions TCP alors que l'app affichait encore un tunnel sain."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "pt", "Como o túnel move os pacotes. Deixe em automático: a pilha mixed do sing-box já matou aqui todas as ligações TCP enquanto a app continuava a indicar um túnel saudável."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "de", "Wie der Tunnel Pakete bewegt. Lass das automatisch: der mixed-Stack von sing-box hat hier jede TCP-Verbindung getötet, während die App den Tunnel weiterhin als gesund meldete."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "ja", "トンネルがパケットをどう運ぶか。自動のままにしてください。sing-box の mixed スタックは、アプリがトンネルを正常と表示したまま TCP 接続をすべて殺したことがあります。"),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "id", "Bagaimana terowongan memindahkan paket. Biarkan otomatis: stack mixed milik sing-box pernah mematikan semua koneksi TCP di sini sementara aplikasi tetap melaporkan terowongan sehat."),
        ("How the tunnel moves packets. Leave this automatic: sing-box's mixed stack has killed every TCP connection here while the app still reported a healthy tunnel.", "tr", "Tünelin paketleri nasıl taşıdığı. Otomatik bırakın: sing-box'ın mixed yığını burada tüm TCP bağlantılarını öldürdüğü hâlde uygulama tüneli sağlıklı göstermeye devam etti."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "ru", "Порт, который слушает ядро. Меняйте только если его уже занимает другая программа на этом Mac."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "zh", "内核监听的端口。只有当这台 Mac 上的其他程序已占用它时才更改。"),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "es", "El puerto en el que escucha el núcleo. Cámbialo solo si otro programa de este Mac ya lo ocupa."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "hi", "वह पोर्ट जिस पर कोर सुनता है। इसे तभी बदलें जब इस Mac का कोई दूसरा प्रोग्राम पहले से उसे लिए हो।"),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "ar", "المنفذ الذي تستمع عليه النواة. لا تغيّره إلا إذا كان برنامج آخر على هذا الـ Mac يشغله."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "fr", "Le port sur lequel le cœur écoute. Ne le changez que si un autre programme de ce Mac l'occupe déjà."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "pt", "A porta em que o núcleo escuta. Mude-a só se outro programa neste Mac já a ocupar."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "de", "Der Port, auf dem der Kern lauscht. Ändere ihn nur, wenn ihn ein anderes Programm auf diesem Mac schon belegt."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "ja", "コアが待ち受けるポート。この Mac の他のプログラムがすでに使っている場合だけ変更してください。"),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "id", "Port tempat core mendengarkan. Ubah hanya jika program lain di Mac ini sudah memakainya."),
        ("The port the core listens on. Change it only if another program on this Mac already holds it.", "tr", "Çekirdeğin dinlediği port. Yalnızca bu Mac'teki başka bir program onu zaten kullanıyorsa değiştirin."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "ru", "Порт, на который в режиме System Proxy направляются приложения, умеющие работать через прокси."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "zh", "在 System Proxy 模式下，支持代理的应用被指向的端口。"),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "es", "El puerto al que se apuntan las apps compatibles con proxy en el modo System Proxy."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "hi", "System Proxy मोड में प्रॉक्सी समझने वाले ऐप जिस पोर्ट पर भेजे जाते हैं।"),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "ar", "المنفذ الذي توجَّه إليه التطبيقات الداعمة للوكيل في وضع System Proxy."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "fr", "Le port vers lequel sont dirigées les apps compatibles proxy en mode System Proxy."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "pt", "A porta para onde as apps compatíveis com proxy são apontadas no modo System Proxy."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "de", "Der Port, auf den proxyfähige Apps im Modus System Proxy gelenkt werden."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "ja", "System Proxy モードでプロキシ対応アプリが向けられるポート。"),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "id", "Port yang dituju aplikasi yang mendukung proxy dalam mode System Proxy."),
        ("The port proxy-aware apps are pointed at in System Proxy mode.", "tr", "System Proxy kipinde vekil destekleyen uygulamaların yönlendirildiği port."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "ru", "Сколько ядро пишет в журнал. Debug нужен для поиска проблемы и очень шумный; warning достаточно на каждый день."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "zh", "内核写入日志的详细程度。Debug 用于排查问题且非常嘈杂；日常用 warning 就够。"),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "es", "Cuánto escribe el núcleo en el registro. Debug sirve para perseguir un problema y es muy ruidoso; warning basta en el día a día."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "hi", "कोर लॉग में कितना लिखता है। Debug किसी समस्या को खोजने के लिए है और बहुत शोरभरा है; रोज़ के लिए warning काफ़ी है।"),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "ar", "مقدار ما تكتبه النواة في السجل. مستوى Debug لتتبّع مشكلة وهو مُزعج جدًا؛ ويكفي warning في الاستخدام اليومي."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "fr", "Ce que le cœur écrit dans le journal. Debug sert à traquer un problème et est très bavard ; warning suffit au quotidien."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "pt", "Quanto o núcleo escreve no registo. Debug serve para perseguir um problema e é muito ruidoso; warning chega no dia a dia."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "de", "Wie viel der Kern ins Protokoll schreibt. Debug dient der Fehlersuche und ist sehr laut; warning reicht im Alltag."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "ja", "コアがログにどれだけ書くか。Debug は問題を追うためのもので非常に冗長です。普段は warning で十分です。"),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "id", "Seberapa banyak core menulis ke log. Debug untuk melacak masalah dan sangat berisik; warning cukup untuk sehari-hari."),
        ("How much the core writes to the log. Debug is for chasing a problem and is very noisy; warning is enough day to day.", "tr", "Çekirdeğin günlüğe ne kadar yazdığı. Debug bir sorunun peşine düşmek içindir ve çok gürültülüdür; günlük kullanımda warning yeter."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "ru", "По таймеру заново скачивает каждый источник, поэтому узлы, которые провайдер добавил или убрал, появляются без нажатий."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "zh", "按定时重新下载每个来源，因此提供方新增或移除的节点无需手动操作即可更新。"),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "es", "Vuelve a descargar cada fuente con un temporizador, así los nodos que tu proveedor añade o quita aparecen sin que pulses nada."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "hi", "हर स्रोत को समय-समय पर फिर से डाउनलोड करता है, ताकि आपका प्रदाता जो नोड जोड़े या हटाए वे बिना कुछ दबाए दिखें।"),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "ar", "يعيد تنزيل كل مصدر وفق مؤقّت، فتظهر العقد التي يضيفها مزوّدك أو يحذفها دون أن تضغط شيئًا."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "fr", "Retélécharge chaque source à intervalle régulier : les nœuds que votre fournisseur ajoute ou retire apparaissent sans rien cliquer."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "pt", "Volta a transferir cada fonte com um temporizador, para que os nós que o seu fornecedor acrescenta ou remove apareçam sem carregar em nada."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "de", "Lädt jede Quelle nach einem Zeitplan neu, sodass Knoten, die dein Anbieter hinzufügt oder entfernt, ohne Zutun erscheinen."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "ja", "各ソースを定期的に再ダウンロードするので、プロバイダーが追加・削除したノードが操作なしで反映されます。"),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "id", "Mengunduh ulang setiap sumber secara berkala, sehingga node yang ditambah atau dihapus penyedia muncul tanpa Anda menekan apa pun."),
        ("Re-downloads every source on a timer, so nodes your provider adds or drops appear without you pressing anything.", "tr", "Her kaynağı belirli aralıklarla yeniden indirir; böylece sağlayıcınızın eklediği ya da kaldırdığı düğümler siz hiçbir şeye basmadan görünür."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "ru", "Отбрасывает соединения с известными рекламными и трекерными доменами ещё до того, как будут применены ваши правила."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "zh", "在应用你自己的规则之前，先丢弃到已知广告和跟踪域名的连接。"),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "es", "Descarta las conexiones a dominios conocidos de publicidad y rastreo antes de consultar tus propias reglas."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "hi", "आपके अपने नियम देखे जाने से पहले ही ज्ञात विज्ञापन और ट्रैकिंग डोमेन के कनेक्शन गिरा देता है।"),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "ar", "يُسقط الاتصالات بنطاقات الإعلانات والتتبّع المعروفة قبل الرجوع إلى قواعدك."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "fr", "Rejette les connexions vers les domaines publicitaires et de pistage connus avant même de consulter vos règles."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "pt", "Descarta as ligações a domínios conhecidos de publicidade e rastreio antes de consultar as suas regras."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "de", "Verwirft Verbindungen zu bekannten Werbe- und Tracking-Domains, bevor deine eigenen Regeln gelten."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "ja", "あなた自身のルールを見る前に、既知の広告・追跡ドメインへの接続を遮断します。"),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "id", "Membuang koneksi ke domain iklan dan pelacak yang dikenal sebelum aturan Anda sendiri diperiksa."),
        ("Drops connections to known advertising and tracking domains before your own rules are consulted.", "tr", "Kendi kurallarınıza bakılmadan önce bilinen reklam ve izleme alan adlarına bağlantıları düşürür."),
