        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "ru", "Читает из имени каждого узла страну, протокол и слова провайдера — Premium, Trial, Game — и показывает их как теги рядом с теми, что вы поставили сами. По ним также работают фильтр и группировка. По умолчанию выключено: это догадки о чужих названиях."),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "zh", "从每个节点的名称中读取国家、协议以及提供方常用的词——Premium、Trial、Game——并作为标签显示在你自己添加的标签旁。它们同样可用于筛选和分组。默认关闭，因为这些只是对他人命名的猜测。"),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "es", "Lee de cada nodo el país, el protocolo y las palabras que usa el proveedor — Premium, Trial, Game — y las muestra como etiquetas junto a las que añades tú. También filtran y agrupan. Desactivado por defecto, porque son conjeturas sobre la nomenclatura ajena."),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "hi", "हर नोड के नाम से देश, प्रोटोकॉल और प्रदाता के शब्द — Premium, Trial, Game — पढ़ता है और उन्हें आपके अपने टैग के साथ दिखाता है। ये फ़िल्टर और समूह भी बनाते हैं। डिफ़ॉल्ट रूप से बंद, क्योंकि ये किसी और के नामकरण के बारे में अनुमान हैं।"),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "ar", "يقرأ من اسم كل عقدة البلد والبروتوكول وكلمات المزوّد — Premium وTrial وGame — ويعرضها كوسوم إلى جانب ما تضيفه بنفسك. وتعمل بها التصفية والتجميع أيضًا. معطّل افتراضيًا لأنها تخمينات حول تسمية غيرك."),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "fr", "Lit dans le nom de chaque nœud le pays, le protocole et les mots d'un fournisseur — Premium, Trial, Game — et les affiche comme étiquettes à côté des vôtres. Elles servent aussi à filtrer et à regrouper. Désactivé par défaut : ce sont des suppositions sur la nomenclature d'autrui."),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "pt", "Lê no nome de cada nó o país, o protocolo e as palavras de um fornecedor — Premium, Trial, Game — e mostra-as como etiquetas ao lado das suas. Também filtram e agrupam. Desligado por omissão, porque são suposições sobre a nomenclatura de outrem."),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "de", "Liest aus dem Namen jedes Knotens das Land, das Protokoll und die Wörter eines Anbieters — Premium, Trial, Game — und zeigt sie als Tags neben deinen eigenen. Sie filtern und gruppieren ebenfalls. Standardmäßig aus, denn es sind Vermutungen über fremde Benennungen."),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "ja", "各ノードの名前から国、プロトコル、プロバイダーが使う語（Premium、Trial、Game）を読み取り、自分で付けたタグの隣に表示します。絞り込みやグループ化にも使えます。他人の命名に対する推測なので既定ではオフです。"),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "id", "Membaca negara, protokol, dan kata yang dipakai penyedia — Premium, Trial, Game — dari nama tiap node lalu menampilkannya sebagai tag di samping tag Anda sendiri. Tag ini juga menyaring dan mengelompokkan. Mati secara bawaan, karena ini tebakan atas penamaan orang lain."),
        ("Reads the country, the protocol and words a provider uses — Premium, Trial, Game — out of each node's name and shows them as tags beside the ones you attach yourself. They also filter and group. Off by default, because they are guesses about someone else's naming.", "tr", "Her düğümün adından ülkeyi, protokolü ve sağlayıcının kullandığı sözcükleri — Premium, Trial, Game — okur ve kendi eklediklerinizin yanında etiket olarak gösterir. Bunlarla süzme ve gruplama da yapılır. Başkasının adlandırması hakkında tahmin oldukları için varsayılan olarak kapalıdır."),
        ("Show the Sources tab", "ru", "Показывать вкладку «Источники»"),
