        ("Show the Sources tab", "id", "Tampilkan tab Sumber"),
        ("Show the Sources tab", "tr", "Kaynaklar sekmesini göster"),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "ru", "Страница о том, откуда взялись серверы, что вернул каждый источник и что не удалось использовать. Скройте её, когда подписки настроены: всё, что на ней есть, остаётся доступным здесь."),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "zh", "这个页面说明服务器来自哪里、每个来源返回了什么以及有哪些内容无法使用。订阅配置好后可以隐藏它，上面的一切在这里依然可用。"),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "es", "La página que dice de dónde vienen los servidores, qué devolvió cada fuente y qué no pudo usarse. Ocúltala cuando tus suscripciones estén listas; todo lo que hay en ella sigue disponible aquí."),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "hi", "यह पृष्ठ बताता है कि सर्वर कहाँ से आए, हर स्रोत ने क्या लौटाया और क्या इस्तेमाल नहीं हो सका। सदस्यताएँ सेट हो जाने पर इसे छिपा दें; इसका सब कुछ यहाँ उपलब्ध रहता है।"),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "ar", "الصفحة التي تبيّن من أين جاءت الخوادم، وما أعاده كل مصدر، وما تعذّر استخدامه. أخفِها بعد إعداد اشتراكاتك؛ فكل ما فيها يبقى متاحًا هنا."),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "fr", "La page qui indique d'où viennent les serveurs, ce que chaque source a renvoyé et ce qui n'a pas pu être utilisé. Masquez-la une fois vos abonnements en place : tout ce qu'elle contient reste accessible ici."),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "pt", "A página que diz de onde vieram os servidores, o que cada fonte devolveu e o que não pôde ser usado. Esconda-a assim que as suas subscrições estiverem prontas; tudo o que lá está continua disponível aqui."),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "de", "Die Seite, die sagt, woher die Server kommen, was jede Quelle geliefert hat und was nicht verwendbar war. Blende sie aus, sobald deine Abos eingerichtet sind; alles darauf bleibt hier verfügbar."),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "ja", "サーバーがどこから来たか、各ソースが何を返したか、何が使えなかったかを示すページです。購読の設定が済んだら隠せます。そこにある情報はすべてここで引き続き利用できます。"),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "id", "Halaman yang menjelaskan asal server, apa yang dikembalikan tiap sumber, dan apa yang tidak bisa dipakai. Sembunyikan setelah langganan Anda siap; semua isinya tetap tersedia di sini."),
        ("The page that says where the servers came from, what each source returned and what it could not use. Hide it once your subscriptions are set up; everything on it stays available here.", "tr", "Sunucuların nereden geldiğini, her kaynağın ne döndürdüğünü ve nelerin kullanılamadığını anlatan sayfa. Abonelikleriniz kurulduktan sonra gizleyin; üzerindeki her şey burada erişilebilir kalır."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "ru", "Резолвер через прокси скрывает ваши запросы; напрямую — быстрее."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "zh", "通过代理访问的解析器会隐藏你的查询；直连的更快。"),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "es", "Un resolvedor alcanzado a través del proxy oculta tus consultas; uno directo es más rápido."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "hi", "प्रॉक्सी के ज़रिए पहुँचा रिज़ॉल्वर आपकी क्वेरी छिपाता है; डायरेक्ट वाला तेज़ होता है।"),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "ar", "المحلِّل الذي يُوصَل إليه عبر الوكيل يخفي استعلاماتك؛ والمباشر أسرع."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "fr", "Un résolveur joint via le proxy masque vos requêtes ; un résolveur direct est plus rapide."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "pt", "Um resolvedor acessado pelo proxy oculta suas consultas; um direto é mais rápido."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "de", "Ein Resolver über den Proxy verbirgt deine Anfragen; einer über Direkt ist schneller."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "ja", "プロキシ経由のリゾルバは問い合わせを隠します。直接接続の方が高速です。"),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "id", "Resolver lewat proxy menyembunyikan kueri Anda; yang langsung lebih cepat."),
        ("A resolver reached through the proxy hides your lookups; one on direct is faster.", "tr", "Proxy üzerinden ulaşılan çözümleyici sorgularınızı gizler; doğrudan olan daha hızlıdır."),
        ("Add one to send a domain or a network through a particular server.", "ru", "Добавьте правило, чтобы направить домен или сеть через конкретный сервер."),
        ("Add one to send a domain or a network through a particular server.", "zh", "添加一条规则，让某个域名或网段走指定服务器。"),
        ("Add one to send a domain or a network through a particular server.", "es", "Añade una para enviar un dominio o una red por un servidor concreto."),
        ("Add one to send a domain or a network through a particular server.", "hi", "किसी डोमेन या नेटवर्क को किसी ख़ास सर्वर से भेजने के लिए एक नियम जोड़ें।"),
        ("Add one to send a domain or a network through a particular server.", "ar", "أضف قاعدة لإرسال نطاق أو شبكة عبر خادم معيّن."),
        ("Add one to send a domain or a network through a particular server.", "fr", "Ajoutez-en une pour faire passer un domaine ou un réseau par un serveur précis."),
        ("Add one to send a domain or a network through a particular server.", "pt", "Adicione uma para enviar um domínio ou uma rede por um servidor específico."),
        ("Add one to send a domain or a network through a particular server.", "de", "Füge eine hinzu, um eine Domain oder ein Netz über einen bestimmten Server zu leiten."),
        ("Add one to send a domain or a network through a particular server.", "ja", "ドメインやネットワークを特定のサーバー経由にするにはルールを追加します。"),
        ("Add one to send a domain or a network through a particular server.", "id", "Tambahkan satu untuk mengirim domain atau jaringan lewat server tertentu."),
