        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "ru", "Адреса, куда iOS отправляет DNS-запросы. Ядро отвечает на них резолвером из «Маршрутизация › DNS»."),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "zh", "iOS 发送查询的地址。核心会用「路由 › DNS」中设置的解析器来应答。"),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "es", "Las direcciones a las que iOS envía sus consultas. El núcleo las responde con el resolvedor de Enrutamiento › DNS."),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "hi", "वे पते जिन पर iOS अपनी क्वेरी भेजता है। कोर इन्हें Routing › DNS में सेट रिज़ॉल्वर से जवाब देता है।"),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "ar", "العناوين التي يرسل إليها iOS استعلاماته. تجيب النواة عنها بالمحلِّل المحدد في التوجيه › DNS."),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "fr", "Les adresses auxquelles iOS envoie ses requêtes. Le cœur y répond avec le résolveur défini dans Routage › DNS."),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "pt", "Os endereços para onde o iOS envia suas consultas. O núcleo as responde com o resolvedor de Roteamento › DNS."),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "de", "Die Adressen, an die iOS seine Anfragen schickt. Der Kern beantwortet sie mit dem Resolver aus Routing › DNS."),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "ja", "iOS が問い合わせを送るアドレスです。コアは「ルーティング › DNS」のリゾルバで応答します。"),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "id", "Alamat tujuan kueri iOS. Inti menjawabnya dengan resolver di Perutean › DNS."),
        ("The addresses iOS sends its lookups to. The core answers them with the resolver set in Routing › DNS.", "tr", "iOS'un sorgularını gönderdiği adresler. Çekirdek bunları Yönlendirme › DNS'teki çözümleyiciyle yanıtlar."),
        ("The log is written while the tunnel is up.", "ru", "Лог пишется, пока туннель включён."),
        ("The log is written while the tunnel is up.", "zh", "隧道运行时才会写入日志。"),
        ("The log is written while the tunnel is up.", "es", "El registro se escribe mientras el túnel está activo."),
        ("The log is written while the tunnel is up.", "hi", "टनल चालू रहने पर ही लॉग लिखा जाता है।"),
        ("The log is written while the tunnel is up.", "ar", "يُكتب السجل أثناء تشغيل النفق."),
        ("The log is written while the tunnel is up.", "fr", "Le journal est écrit tant que le tunnel est actif."),
        ("The log is written while the tunnel is up.", "pt", "O log é gravado enquanto o túnel está ativo."),
        ("The log is written while the tunnel is up.", "de", "Das Protokoll wird geschrieben, solange der Tunnel läuft."),
        ("The log is written while the tunnel is up.", "ja", "ログはトンネル稼働中に書き込まれます。"),
        ("The log is written while the tunnel is up.", "id", "Log ditulis selama terowongan aktif."),
        ("The log is written while the tunnel is up.", "tr", "Günlük, tünel açıkken yazılır."),
        ("The provider's device limit is reached.", "ru", "Достигнут лимит устройств у провайдера."),
        ("The provider's device limit is reached.", "zh", "已达到服务商的设备上限。"),
        ("The provider's device limit is reached.", "es", "Se alcanzó el límite de dispositivos del proveedor."),
        ("The provider's device limit is reached.", "hi", "प्रदाता की डिवाइस सीमा पूरी हो गई है।"),
        ("The provider's device limit is reached.", "ar", "تم بلوغ حد الأجهزة لدى المزوّد."),
