        ("The provider's device limit is reached.", "ja", "プロバイダーのデバイス上限に達しました。"),
        ("The provider's device limit is reached.", "id", "Batas perangkat penyedia telah tercapai."),
        ("The provider's device limit is reached.", "tr", "Sağlayıcının cihaz sınırına ulaşıldı."),
        ("These come with a subscription and are replaced on every refresh.", "ru", "Они приходят с подпиской и заменяются при каждом обновлении."),
        ("These come with a subscription and are replaced on every refresh.", "zh", "这些随订阅提供，每次刷新都会替换。"),
        ("These come with a subscription and are replaced on every refresh.", "es", "Vienen con una suscripción y se reemplazan en cada actualización."),
        ("These come with a subscription and are replaced on every refresh.", "hi", "ये सब्सक्रिप्शन के साथ आते हैं और हर रीफ़्रेश पर बदल दिए जाते हैं।"),
        ("These come with a subscription and are replaced on every refresh.", "ar", "تأتي هذه مع الاشتراك وتُستبدل عند كل تحديث."),
        ("These come with a subscription and are replaced on every refresh.", "fr", "Ils viennent avec un abonnement et sont remplacés à chaque mise à jour."),
        ("These come with a subscription and are replaced on every refresh.", "pt", "Vêm com uma assinatura e são substituídos a cada atualização."),
        ("These come with a subscription and are replaced on every refresh.", "de", "Diese kommen mit einem Abo und werden bei jeder Aktualisierung ersetzt."),
        ("These come with a subscription and are replaced on every refresh.", "ja", "これらはサブスクリプションに含まれ、更新のたびに置き換えられます。"),
        ("These come with a subscription and are replaced on every refresh.", "id", "Ini datang bersama langganan dan diganti setiap pembaruan."),
        ("These come with a subscription and are replaced on every refresh.", "tr", "Bunlar abonelikle gelir ve her yenilemede değiştirilir."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "ru", "Это правило сопоставляет приложения или инвертировано. Так умеет только ядро sing-box на Mac, поэтому здесь оно не применяется."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "zh", "此规则匹配应用程序或已反转。只有 Mac 上的 sing-box 核心能做到，因此此版本会忽略它。"),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "es", "Esta regla coincide con aplicaciones o está invertida. Solo el núcleo sing-box del Mac puede hacerlo, así que esta versión la omite."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "hi", "यह नियम ऐप्स से मेल खाता है या उलटा है। ऐसा केवल Mac पर sing-box कोर कर सकता है, इसलिए यह बिल्ड इसे छोड़ देता है।"),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "ar", "هذه القاعدة تطابق تطبيقات أو معكوسة. لا يستطيع ذلك إلا نواة sing-box على Mac، لذا يتجاهلها هذا الإصدار."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "fr", "Cette règle cible des applications ou est inversée. Seul le cœur sing-box du Mac sait le faire, cette version l'ignore donc."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "pt", "Esta regra corresponde a aplicativos ou está invertida. Só o núcleo sing-box no Mac faz isso, então esta versão a ignora."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "de", "Diese Regel erkennt Apps oder ist invertiert. Das kann nur der sing-box-Kern auf dem Mac, daher lässt dieser Build sie weg."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "ja", "このルールはアプリに一致するか反転されています。それができるのは Mac の sing-box コアだけなので、このビルドでは除外されます。"),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "id", "Aturan ini mencocokkan aplikasi atau dibalik. Hanya inti sing-box di Mac yang bisa, jadi build ini mengabaikannya."),
        ("This rule matches applications or is inverted. Only the sing-box core on the Mac can do that, so this build leaves it out.", "tr", "Bu kural uygulamaları eşler veya ters çevrilmiştir. Bunu yalnızca Mac'teki sing-box çekirdeği yapabilir, bu sürüm onu atlar."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "ru", "Если выключено, DNS-запросы идут через туннель как обычный трафик к серверам из настроек, а правила ниже не действуют."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "zh", "关闭后，查询会作为普通流量经隧道发往设置中的服务器，下面的规则不会生效。"),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "es", "Desactivado, las consultas viajan por el túnel como tráfico normal a los servidores de Ajustes y las reglas de abajo no hacen nada."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "hi", "बंद होने पर क्वेरी सामान्य ट्रैफ़िक की तरह टनल से सेटिंग्स के सर्वरों तक जाती हैं, और नीचे के नियम काम नहीं करते।"),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "ar", "عند الإيقاف تمرّ الاستعلامات عبر النفق كحركة عادية إلى الخوادم في الإعدادات، ولا تعمل القواعد أدناه."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "fr", "Désactivé, les requêtes passent dans le tunnel comme du trafic ordinaire vers les serveurs des Réglages, et les règles ci-dessous sont sans effet."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "pt", "Desligado, as consultas passam pelo túnel como tráfego comum para os servidores dos Ajustes, e as regras abaixo não fazem nada."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "de", "Ausgeschaltet laufen Anfragen als normaler Verkehr durch den Tunnel zu den Servern aus den Einstellungen, und die Regeln unten wirken nicht."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "ja", "オフにすると、問い合わせは通常のトラフィックとしてトンネル経由で設定のサーバーへ送られ、下のルールは機能しません。"),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "id", "Jika mati, kueri lewat terowongan sebagai lalu lintas biasa ke server di Pengaturan, dan aturan di bawah tidak berlaku."),
        ("With this off, lookups travel through the tunnel as ordinary traffic to the servers in Settings, and the rules below do nothing.", "tr", "Kapalıyken sorgular tünelden normal trafik olarak Ayarlar'daki sunuculara gider ve aşağıdaki kurallar işe yaramaz."),
        ("Without the database, rules that name geosite: or geoip: are left out instead of stopping the tunnel.", "ru", "Без базы правила с geosite: или geoip: пропускаются, а не ломают туннель."),
        ("Without the database, rules that name geosite: or geoip: are left out instead of stopping the tunnel.", "zh", "没有数据库时，引用 geosite: 或 geoip: 的规则会被忽略，而不会让隧道无法启动。"),
